n  /// Secure opaque token encoded in the QR code\n  qrCode       String       @unique\n  status       TicketStatus @default(ACTIVE)\n  issuedAt     DateTime     @default(now())\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event             Event                 @relation(fields: [eventId], references: [id])\n  user              User                  @relation(fields: [userId], references: [id])\n  /// Ticket owns the FK — EventSeat.ticket is the virtual back-relation\n  eventSeat         EventSeat?            @relation(fields: [eventSeatId], references: [id])\n  ticketType        TicketType            @relation(fields: [ticketTypeId], references: [id])\n  payment           Payment?\n  review            EventReview?\n  groupSlot         GroupOrderSlot?\n  isComplimentary   Boolean               @default(false)\n  sessionEnrolments SessionEnrolment[]\n  timeSlotTickets   TimeSlotTicket[]\n  tableAssignments  TableSeatAssignment[]\n\n  @@index([eventId])\n  @@index([userId])\n  @@map(\"tickets\")\n}\n\n// ─── Payment ──────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id          String @id @default(cuid())\n  ticketId    String @unique\n  organizerId String\n  userId      String\n  eventId     String\n\n  /// Amount user paid in minor units (kobo)\n  amount             Int\n  currency           String @default(\"NGN\")\n  /// Platform fee % snapshotted at purchase time\n  platformFeePercent Float\n  /// Platform fee amount in minor units\n  platformFeeAmount  Int\n  /// Net amount organizer will receive (amount - fee)\n  netAmount          Int\n\n  status                PaymentStatus @default(PENDING)\n  /// Paystack payment reference\n  paystackReference     String?       @unique\n  /// Paystack transaction id\n  paystackTransactionId String?\n\n  /// FK to the payout request this payment is included in (set when payout is approved)\n  payoutRequestId String?\n\n  /// FK to the promo code used for this payment (nullable)\n  promoCodeId    String?\n  /// Discount amount applied in minor units (0 if no promo code used)\n  discountAmount Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  ticket        Ticket          @relation(fields: [ticketId], references: [id])\n  organizer     Organizer       @relation(fields: [organizerId], references: [id])\n  user          User            @relation(fields: [userId], references: [id])\n  event         Event           @relation(fields: [eventId], references: [id])\n  payoutRequest PayoutRequest?  @relation(\"PaymentToPayoutRequest\", fields: [payoutRequestId], references: [id])\n  promoCode     PromoCode?      @relation(fields: [promoCodeId], references: [id])\n  refundRequest RefundRequest?\n  groupSlot     GroupOrderSlot?\n\n  @@index([organizerId])\n  @@index([eventId])\n  @@index([userId])\n  @@map(\"payments\")\n}\n\n// ─── Payout Request ───────────────────────────────────────────────────────────\n\nmodel PayoutRequest {\n  id          String @id @default(cuid())\n  organizerId String\n  eventId     String\n  /// Total gross collected for this event (sum of payment.amount)\n  grossAmount Int\n  /// Total platform fees deducted\n  totalFees   Int\n  /// Net amount to be paid out\n  netAmount   Int\n  currency    String @default(\"NGN\")\n\n  status     PayoutStatus @default(PENDING)\n  /// Admin who approved/rejected\n  reviewedBy String?\n  reviewNote String?      @db.Text\n  reviewedAt DateTime?\n\n  /// Paystack Transfer code (set when transfer is initiated)\n  paystackTransferCode  String?\n  /// Paystack recipient code for the organizer's bank\n  paystackRecipientCode String?\n  completedAt           DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organizer Organizer @relation(fields: [organizerId], references: [id])\n  event     Event     @relation(fields: [eventId], references: [id])\n  payments  Payment[] @relation(\"PaymentToPayoutRequest\")\n\n  @@unique([organizerId, eventId])\n  @@index([organizerId])\n  @@index([status])\n  @@map(\"payout_requests\")\n}\n\n// ─── Event Review ─────────────────────────────────────────────────────────────\n\nmodel EventReview {\n  id       String    @id @default(cuid())\n  eventId  String\n  userId   String\n  ticketId String    @unique\n  /// 1–5 stars\n  rating   Int\n  body     String?   @db.Text\n  /// Organizer public reply\n  reply    String?   @db.Text\n  replyAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event  Event  @relation(fields: [eventId], references: [id])\n  user   User   @relation(fields: [userId], references: [id])\n  ticket Ticket @relation(fields: [ticketId], references: [id])\n\n  @@index([eventId])\n  @@index([userId])\n  @@map(\"event_reviews\")\n}\n\n// ─── Refund Request ───────────────────────────────────────────────────────────\n\nmodel RefundRequest {\n  id        String @id @default(cuid())\n  paymentId String @unique\n  userId    String\n  eventId   String\n  /// User's reason for the complaint/refund\n  reason    String @db.Text\n\n  status           RefundStatus @default(OPEN)\n  /// Admin decision note\n  reviewNote       String?      @db.Text\n  reviewedBy       String?\n  reviewedAt       DateTime?\n  /// Paystack refund id (set when refund is processed)\n  paystackRefundId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  payment Payment @relation(fields: [paymentId], references: [id])\n  user    User    @relation(fields: [userId], references: [id])\n  event   Event   @relation(fields: [eventId], references: [id])\n\n  @@index([userId])\n  @@index([eventId])\n  @@index([status])\n  @@map(\"refund_requests\")\n}\n\n// ─── Group Order ──────────────────────────────────────────────────────────────\n\nmodel GroupOrder {\n  id                 String           @id @default(cuid())\n  eventId            String\n  initiatorId        String\n  /// Short shareable code, e.g. \"GRP-8F3A2C\"\n  code               String           @unique\n  status             GroupOrderStatus @default(PENDING)\n  /// All-or-nothing: if true the order auto-cancels when it expires with unpaid slots.\n  /// If false, paid slots become confirmed and unpaid slots are released.\n  requireFullPayment Boolean          @default(false)\n  /// Hard deadline — BullMQ fires expiry job at this time\n  expiresAt          DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event     Event            @relation(fields: [eventId], references: [id])\n  initiator User             @relation(\"GroupOrderInitiator\", fields: [initiatorId], references: [id])\n  slots     GroupOrderSlot[]\n\n  @@index([eventId, status])\n  @@index([initiatorId])\n  @@map(\"group_orders\")\n}\n\n// ─── Group Order Slot ─────────────────────────────────────────────────────────\n\nmodel GroupOrderSlot {\n  id           String  @id @default(cuid())\n  groupOrderId String\n  /// For RESERVED events: the specific EventSeat being held\n  eventSeatId  String?\n  /// For GA events: the ticket type the member will purchase\n  ticketTypeId String?\n  /// Price in minor units (kobo) — snapshotted at group creation\n  price        Int\n  currency     String  @default(\"NGN\")\n  /// Optional label the initiator sets — e.g. \"John's seat\"\n  label        String?\n\n  status    GroupSlotStatus @default(OPEN)\n  /// User who claimed this slot (null = unclaimed)\n  claimedBy String?\n  claimedAt DateTime?\n  /// Set when member completes payment\n  paymentId String?         @unique\n  /// Set when ticket is issued after payment\n  ticketId  String?         @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  groupOrder GroupOrder  @relation(fields: [groupOrderId], references: [id], onDelete: Cascade)\n  eventSeat  EventSeat?  @relation(fields: [eventSeatId], references: [id])\n  ticketType TicketType? @relation(fields: [ticketTypeId], references: [id])\n  claimer    User?       @relation(\"GroupSlotClaimer\", fields: [claimedBy], references: [id])\n  payment    Payment?    @relation(fields: [paymentId], references: [id])\n  ticket     Ticket?     @relation(fields: [ticketId], references: [id])\n\n  @@index([groupOrderId, status])\n  @@map(\"group_order_slots\")\n}\n\n// ─── User Calendar ────────────────────────────────────────────────────────────\n\nmodel UserCalendar {\n  id          String   @id @default(cuid())\n  userId      String\n  title       String\n  description String?  @db.Text\n  /// Hex color for display, e.g. \"#7c3aed\"\n  color       String   @default(\"#7c3aed\")\n  /// Opaque token used for public share links / ICS export\n  shareToken  String   @unique @default(cuid())\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  user   User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  events CalendarEvent[]\n  shares CalendarShare[]\n\n  @@index([userId])\n  @@map(\"user_calendars\")\n}\n\nmodel CalendarEvent {\n  id            String    @id @default(cuid())\n  calendarId    String\n  title         String\n  description   String?   @db.Text\n  location      String?\n  startsAt      DateTime\n  endsAt        DateTime?\n  /// true = all-day event (time portion is ignored in display)\n  allDay        Boolean   @default(false)\n  /// Optional link to a SWITCH platform Event\n  linkedEventId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  calendar    UserCalendar @relation(fields: [calendarId], references: [id], onDelete: Cascade)\n  linkedEvent Event?       @relation(\"CalendarLinkedEvent\", fields: [linkedEventId], references: [id], onDelete: SetNull)\n\n  @@index([calendarId, startsAt])\n  @@map(\"calendar_events\")\n}\n\nmodel CalendarShare {\n  id           String   @id @default(cuid())\n  calendarId   String\n  /// The user this calendar is shared with\n  sharedWithId String\n  /// Whether the recipient can add events to their own calendar from this share\n  canCopy      Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  calendar   UserCalendar @relation(fields: [calendarId], references: [id], onDelete: Cascade)\n  sharedWith User         @relation(\"CalendarSharedWith\", fields: [sharedWithId], references: [id], onDelete: Cascade)\n\n  @@unique([calendarId, sharedWithId])\n  @@index([sharedWithId])\n  @@map(\"calendar_shares\")\n}\n\n// ─── Promo Code ───────────────────────────────────────────────────────────────\n\nmodel PromoCode {\n  id           String  @id @default(cuid())\n  organizerId  String\n  /// null = applies to all events by this organizer\n  eventId      String?\n  /// null = applies to all ticket types on the scoped event\n  ticketTypeId String?\n\n  /// Human-readable code, e.g. \"EARLYBIRD20\" — stored uppercase\n  code          String       @unique\n  discountType  DiscountType\n  /// Percentage (1–100) or flat amount in minor units (kobo)\n  discountValue Int\n  /// null = unlimited uses\n  maxUses       Int?\n  /// How many times this code has been successfully used\n  usedCount     Int          @default(0)\n  /// null = never expires\n  expiresAt     DateTime?\n  isActive      Boolean      @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  organizer  Organizer   @relation(fields: [organizerId], references: [id], onDelete: Cascade)\n  event      Event?      @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  ticketType TicketType? @relation(fields: [ticketTypeId], references: [id], onDelete: SetNull)\n  payments   Payment[]\n\n  @@index([code])\n  @@index([organizerId])\n  @@index([eventId])\n  @@map(\"promo_codes\")\n}\n\n// ─── Waitlist Entry ───────────────────────────────────────────────────────────\n\nmodel WaitlistEntry {\n  id             String         @id @default(cuid())\n  eventId        String\n  userId         String\n  ticketTypeId   String\n  requestedQty   Int            @default(1)\n  position       Int\n  status         WaitlistStatus @default(PENDING)\n  /// Set when status transitions to OFFERED\n  offerExpiresAt DateTime?\n  /// FK to the Reservation created when the offer is made\n  reservationId  String?        @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event       Event        @relation(fields: [eventId], references: [id])\n  user        User         @relation(fields: [userId], references: [id])\n  ticketType  TicketType   @relation(fields: [ticketTypeId], references: [id])\n  reservation Reservation? // back-relation via Reservation.waitlistEntryId\n\n  @@unique([userId, ticketTypeId])\n  @@index([ticketTypeId, status, position])\n  @@index([eventId])\n  @@map(\"waitlist_entries\")\n}\n\n// ─── Time Slot ────────────────────────────────────────────────────────────────\n\nmodel TimeSlot {\n  id       String           @id @default(cuid())\n  eventId  String\n  label    String\n  startsAt DateTime\n  endsAt   DateTime\n  capacity Int\n  price    Int\n  currency String           @default(\"NGN\")\n  status   TicketTypeStatus @default(ACTIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event   Event            @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  tickets TimeSlotTicket[]\n\n  @@index([eventId, status])\n  @@map(\"time_slots\")\n}\n\n// ─── Time Slot Ticket (join) ──────────────────────────────────────────────────\n\nmodel TimeSlotTicket {\n  id         String   @id @default(cuid())\n  ticketId   String\n  timeSlotId String\n  createdAt  DateTime @default(now())\n\n  ticket   Ticket   @relation(fields: [ticketId], references: [id])\n  timeSlot TimeSlot @relation(fields: [timeSlotId], references: [id])\n\n  @@unique([ticketId, timeSlotId])\n  @@map(\"time_slot_tickets\")\n}\n\n// ─── Event Session ────────────────────────────────────────────────────────────\n\nmodel EventSession {\n  id            String               @id @default(cuid())\n  eventId       String\n  title         String\n  description   String?              @db.Text\n  facilitator   String?\n  startsAt      DateTime\n  endsAt        DateTime\n  capacity      Int?\n  price         Int                  @default(0)\n  currency      String               @default(\"NGN\")\n  inclusionMode SessionInclusionMode @default(INCLUDED)\n  status        TicketTypeStatus     @default(ACTIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event      Event              @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  enrolments SessionEnrolment[]\n\n  @@index([eventId])\n  @@map(\"event_sessions\")\n}\n\n// ─── Session Enrolment ────────────────────────────────────────────────────────\n\nmodel SessionEnrolment {\n  id        String   @id @default(cuid())\n  ticketId  String\n  sessionId String\n  createdAt DateTime @default(now())\n\n  ticket  Ticket       @relation(fields: [ticketId], references: [id])\n  session EventSession @relation(fields: [sessionId], references: [id])\n\n  @@unique([ticketId, sessionId])\n  @@index([sessionId])\n  @@map(\"session_enrolments\")\n}\n\n// ─── Table Seat Assignment ────────────────────────────────────────────────────\n\n/// Per-seat name assignments for table reservations where requiresAssignedSeating = true\nmodel TableSeatAssignment {\n  id           String   @id @default(cuid())\n  ticketId     String\n  ticketTypeId String\n  seatNumber   Int\n  attendeeName String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  ticket     Ticket     @relation(fields: [ticketId], references: [id])\n  ticketType TicketType @relation(fields: [ticketTypeId], references: [id])\n\n  @@unique([ticketId, seatNumber])\n  @@map(\"table_seat_assignments\")\n}\n\n// ─── Audit Log ────────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id         String          @id @default(cuid())\n  entityType AuditEntityType\n  entityId   String\n  action     AuditAction\n  oldStatus  String?\n  newStatus  String?\n  /// userId or \"system\" for background jobs\n  actor      String\n  metadata   Json?\n  createdAt  DateTime        @default(now())\n\n  @@index([entityType, entityId])\n  @@index([actor])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n",
